"""Evaluate text generated by runtime-supplied native Koine grammars in SLIP."""

import asyncio
from pathlib import Path
import tempfile

from safer_yaml import load

from koine import Parser, Transpiler
from slip.slip_runtime import ScriptRunner


async def main():
    root = Path(__file__).resolve().parents[2]
    parser = Parser(load(root / "tests/calculator_parser.yaml"))
    transpiler = Transpiler(load(Path(__file__).with_name("math_to_slip.yaml")))
    runner = ScriptRunner()
    plain = await runner.handle_script("10 + 5 * 2")
    assert plain.status == "ok", plain.error_message
    assert plain.value == 30
    cases = [("10 + 5 * 2", 20), ("(10 + 5) * 2", 30), ("8 - 2 - 1", 5),
             ("2 ^ 3 ^ 2", 512), ("(2 ^ 3) ^ 2", 64), ("9007199254740993 + 1", 9007199254740994)]
    with tempfile.TemporaryDirectory() as directory:
        for index, (source, expected) in enumerate(cases):
            parsed = parser.parse(source, start_rule="expression")
            assert parsed["status"] == "success", parsed
            generated = transpiler.transpile(parsed["ast"])
            path = Path(directory) / f"math-{index}.slip"
            path.write_text(generated, encoding="utf-8")
            saved = path.read_text(encoding="utf-8")
            assert saved == generated
            result = await runner.handle_script(saved)
            assert result.status == "ok", (source, saved, result.error_message)
            assert result.value == expected, (source, saved, result.value, expected)
    print(f"{len(cases)} saved native math-to-SLIP programs evaluated correctly; ordinary SLIP remains left-to-right")


if __name__ == "__main__":
    asyncio.run(main())
